-- Bootstrap schema is also generated by SQLAlchemy Base.metadata.create_all.
-- 配比敏感性：各批占比上下限、后台计算任务、已发布版本留档。
CREATE TABLE IF NOT EXISTS mix_bounds(id SERIAL PRIMARY KEY,assessment_id INTEGER NOT NULL REFERENCES assessments(id),lot VARCHAR(60) NOT NULL,lower FLOAT NOT NULL,upper FLOAT NOT NULL,updated_by VARCHAR(120) NOT NULL,updated_at VARCHAR(40) NOT NULL,CONSTRAINT uq_mix_bounds_assessment_lot UNIQUE(assessment_id,lot));
CREATE TABLE IF NOT EXISTS mix_studies(id SERIAL PRIMARY KEY,assessment_id INTEGER NOT NULL REFERENCES assessments(id),status VARCHAR(20) NOT NULL,input_fingerprint VARCHAR(64) NOT NULL,result JSON,error TEXT NOT NULL,created_by VARCHAR(120) NOT NULL,created_at VARCHAR(40) NOT NULL,finished_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS mix_publications(id SERIAL PRIMARY KEY,assessment_id INTEGER NOT NULL REFERENCES assessments(id),study_id INTEGER NOT NULL REFERENCES mix_studies(id),version INTEGER NOT NULL,report JSON NOT NULL,fingerprint VARCHAR(64) NOT NULL,stale BOOLEAN NOT NULL,published_by VARCHAR(120) NOT NULL,published_at VARCHAR(40) NOT NULL,CONSTRAINT uq_mix_pub_assessment_study UNIQUE(assessment_id,study_id),CONSTRAINT uq_mix_pub_assessment_version UNIQUE(assessment_id,version));
